def gen(rng):
    def fmt(qs):
        return str(len(qs)) + '\n' + '\n'.join('%d %d' % p for p in qs)

    M = 2 ** 32 - 1

    def hi_ones(p):
        return M ^ ((1 << p) - 1)

    tests = [fmt([(M, 0)]), fmt([(0, 31)]), fmt([(0x80000000, 31)]), fmt([(0x7FFFFFFF, 31)]),
             fmt([(0xFFFF0000, 16), (0xFFFF0000, 15), (0xFFFF0000, 17)]),
             fmt([(M, 31), (M, 15), (M, 0)]), fmt([(0, 0)]), fmt([(M - 1, 0), (M - 1, 1)])]
    for _ in range(30):
        qs = []
        for _ in range(rng.randint(1, 12)):
            p = rng.randint(0, 31)
            mode = rng.randint(0, 3)
            if mode == 0:
                x = rng.randint(0, M)
            elif mode == 1:
                x = hi_ones(p) | rng.randint(0, (1 << p) - 1) if p else M
            elif mode == 2:
                x = (hi_ones(p) | rng.randint(0, (1 << p) - 1) if p else M) ^ (1 << rng.randint(p, 31))
            else:
                x = hi_ones(p)
            qs.append((x, p))
        tests.append(fmt(qs))
    def big(n, mixed):
        qs = []
        for _ in range(n):
            p = rng.randint(0, 31)
            if mixed and rng.random() < 0.5:
                x = (hi_ones(p) | rng.randint(0, (1 << p) - 1)) if p else M
            else:
                x = rng.randint(0, M)
            qs.append((x, p))
        return qs
    tests.append(fmt(big(100000, True)))
    tests.append(fmt(big(100000, False)))
    tests.append(fmt([(M, 0)] * 100000))
    return tests

